def find_smallest_n():
    for n in range(1, 1000):
        # The condition is n^2 - 3nr + 3r^2 = 2007 for some 0 <= r <= n
        # 3r^2 - 3nr + (n^2 - 2007) = 0
        # discriminant D = 9n^2 - 12(n^2 - 2007) = 12*2007 - 3n^2
        D = 12 * 2007 - 3 * n**2
        if D < 0:
            continue

        import math
        sqrt_D = math.isqrt(D)
        if sqrt_D * sqrt_D == D:
            # r = (3n +/- sqrt_D) / 6
            for sign in [1, -1]:
                numerator = 3 * n + sign * sqrt_D
                if numerator % 6 == 0:
                    r = numerator // 6
                    if 0 <= r <= n:
                        return n
    return None

print(find_smallest_n())
